setup.run:
printf 'server {
    listen 80;
    server_name ana.example;
    root /var/www/ana.example;
    index index.html;
}
' > /etc/nginx/sites-available/ana.example && ln -s /etc/nginx/sites-available/ana.example /etc/nginx/sites-enabled/ && rm /etc/nginx/sites-enabled/default && systemctl reload nginx
